appearances.css:
.app{padding:6px;display:grid;grid-template-columns:repeat(24,minmax(0,1fr));column-gap:4px;row-gap:2px;font-size:10px}
.disp{grid-area:1/1/2/-1;font-size:11px;padding:3px 8px;min-height:0;margin:0;gap:2px 12px}
.disp .lim{font-size:8px}
.stt{grid-area:10/1/11/-1;margin:0;font-size:9px}
h3{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:8px;letter-spacing:.08em;margin:3px 0 0;padding:0;border:0}
.app>:nth-child(2){grid-area:2/1/3/25}
.app>:nth-child(3){grid-area:3/1/4/25}
.app>:nth-child(4){grid-area:4/1/5/13}
.app>:nth-child(5){grid-area:5/1/6/13}
.app>:nth-child(6){grid-area:4/13/5/25}
.app>:nth-child(7){grid-area:5/13/6/25}
.app>:nth-child(8){grid-area:6/1/7/13}
.app>:nth-child(9){grid-area:7/1/8/13}
.app>:nth-child(10){grid-area:6/13/7/25}
.app>:nth-child(11){grid-area:7/13/8/25}
.app>:nth-child(12){grid-area:8/1/9/9}
.app>:nth-child(13){grid-area:9/1/10/9}
.app>:nth-child(14){grid-area:8/9/9/16}
.app>:nth-child(15){grid-area:9/9/10/16}
.app>:nth-child(16){grid-area:8/16/9/25}
.app>:nth-child(17){grid-area:9/16/10/25}
.grid{justify-content:space-around;display:flex;flex-wrap:wrap;align-items:center;gap:3px 0;padding:3px 2px;border:1px solid var(--line,#30363f);border-radius:4px;background:color-mix(in srgb,var(--fg,#e2e6ea) 3%,transparent)}
.c{flex:1 1 30px;display:grid;justify-items:center;align-content:center;gap:0;min-width:0;padding:0 1px}
label.c{flex:0 0 auto;padding:0 2px}
.c .lab{display:contents}
.c .kn{order:1;width:28px!important;height:28px!important;justify-self:center!important}
.c .kn svg{width:100%;height:100%}
.c output{order:2;font-size:7.5px;line-height:1.1;color:var(--muted,#97a1ad);white-space:nowrap;text-align:center}
.c .lab span{order:3;font-size:7px;letter-spacing:-.02em;line-height:1.1;text-transform:none;text-align:center;max-width:100%;overflow:visible;text-overflow:clip;white-space:normal}
label.c select{order:1;width:46px;max-width:100%;text-overflow:ellipsis;font-size:9px;padding:3px 10px 3px 3px;border-radius:4px;appearance:none;-webkit-appearance:none;background:linear-gradient(45deg,transparent 50%,var(--muted,#97a1ad) 50%) calc(100% - 7px) 55%/4px 4px no-repeat,linear-gradient(135deg,var(--muted,#97a1ad) 50%,transparent 50%) calc(100% - 3px) 55%/4px 4px no-repeat,var(--field,#20252d)}
.grid>button{flex:0 1 auto;font-size:9.5px;padding:4px 5px;margin:0 1px;border-radius:4px}
select[data-pk-id=timing]{width:94px!important}select[data-pk-id=mode]{width:58px!important}select[data-pk-id=modType]{width:70px!important}select[data-pk-id=glide]{width:64px!important}select[data-pk-id=divL],select[data-pk-id=divR]{width:46px!important}select[data-pk-id=feelL],select[data-pk-id=feelR]{width:52px!important}
